CREATE TABLE ARTIFACTS (
  ARTIFACT_ID INTEGER NOT NULL PRIMARY KEY,
  BURIAL_ID INTEGER NOT NULL,
  SITE_ID INTEGER NOT NULL,
  TYPE VARCHAR(45) NOT NULL,
  SUBTYPE VARCHAR(45) NOT NULL,
  MATERIAL VARCHAR(45),
  COLOUR VARCHAR(45),
  DECORATED BOOLEAN NOT NULL,
  INSCRIBED BOOLEAN NOT NULL,
  DESCRIPTION VARCHAR(100),
  CONSTRAINT FK_ARTIFACTS_BURIAL FOREIGN KEY (BURIAL_ID) REFERENCES BURIALS ON DELETE RESTRICT,
  CONSTRAINT FK_ARTIFACTS_SITE  FOREIGN KEY (SITE_ID) REFERENCES SITES ON DELETE RESTRICT
);
